'use strict';
/* Focused fixes layered after long-form v2. */
const lfTabCore=lfTab;
lfTab=function(s,tab){lfTabCore(s,tab);if(!lfChapters(s).length&&['overview','chapters'].includes(tab)){document.querySelectorAll('#longformDialog [data-lf-next]').forEach(b=>b.textContent=b.textContent.replace('2','1'))}};
document.addEventListener('click',e=>{const b=e.target.closest('[data-lf-addplan]');if(!b)return;const d=$('#longformDialog');if(!d?.open)return;const s=db.series.find(x=>x.id===d.dataset.series);if(!s)return;e.preventDefault();e.stopImmediatePropagation();const sd=lfData(s),title=prompt('Tên mục dàn ý');if(!title)return;const kind=(prompt('Loại: volume / arc / chapter / scene / note','arc')||'arc').trim();if(!lfKinds[kind])return toast('Loại dàn ý không hợp lệ.');let parentId='';const parents=sd.plans.filter(x=>x.kind!=='scene');if(parents.length){const choices=parents.map((x,i)=>(i+1)+'. '+lfPath(s,x)).join('\n');const pick=Number(prompt('Chọn số mục cha, nhập 0 nếu là cấp gốc:\n'+choices,'0')||0);if(pick<0||pick>parents.length)return toast('Mục cha không hợp lệ.');if(pick)parentId=parents[pick-1].id}const start=kind==='note'?0:Number(prompt('Chương bắt đầu','1')||1),end=['chapter','scene'].includes(kind)?start:Number(prompt('Chương kết thúc',String(start||1))||start);sd.plans.push({id:uid(),title,body:prompt('Nội dung / mục tiêu','')||'',kind,parentId,startChapter:start,endChapter:end,order:sd.plans.length});lfSave(s,'plan')},true);
